1	package payflow
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"math"
8		"os"
9		"path/filepath"
10	)
11	
12	// atomicWrite 将 v 以 JSON 原子写入 path：
13	//  1. 写入同目录临时文件并 fsync；
14	//  2. rename 覆盖目标文件（同文件系统内原子）；
15	//  3. 尽力 fsync 目录，帮助 rename 跨掉电容灾。
16	//
17	// 关键不变式：磁盘上的目标文件在任意时刻要么是完整旧内容，
18	// 要么是完整新内容（临时文件先 fsync 后改名，JSON 只写一个文档）。
19	// 进程在保存期间崩溃，重开只能看到完整的旧状态或新状态，
20	// 不会出现“扣款无记录”或“记录未扣款”。
21	func atomicWrite(path string, v any) error {
22		perm := os.FileMode(0o600)
23		data, err := json.Marshal(v)
24		if err != nil {
25			return ledgerError(ErrStorage, "encode ledger: %v", err)
26		}
27		data = append(data, '\n')
28	
29		dir := filepath.Dir(path)
30		if err := os.MkdirAll(dir, 0o700); err != nil {
31			return ledgerError(ErrStorage, "create ledger directory %s: %v", dir, err)
32		}
33	
34		tmp, err := os.CreateTemp(dir, ".ledger-*.tmp")
35		if err != nil {
36			return ledgerError(ErrStorage, "create temp file in %s: %v", dir, err)
37		}
38		tmpName := tmp.Name()
39		removeTemp := func() { _ = os.Remove(tmpName) }
40	
41		if _, err := tmp.Write(data); err != nil {
42			_ = tmp.Close()
43			removeTemp()
44			return ledgerError(ErrStorage, "write temp file: %v", err)
45		}
46		if err := tmp.Sync(); err != nil {
47			_ = tmp.Close()
48			removeTemp()
49			return ledgerError(ErrStorage, "fsync temp file: %v", err)
50		}
51		if err := tmp.Close(); err != nil {
52			removeTemp()
53			return ledgerError(ErrStorage, "close temp file: %v", err)
54		}
55		if err := os.Chmod(tmpName, perm); err != nil {
56			removeTemp()
57			return ledgerError(ErrStorage, "chmod temp file: %v", err)
58		}
59		// rename 之后新文件已完整就位。即便此后目录 fsync 失败，也不能再回滚：
60		// 回滚内存会与磁盘（已是新状态）分叉。目录 fsync 仅影响掉电后目录项的
61		// 持久性，而可能出现的两种结局（旧文件/新文件）都是完整状态。
62		if err := os.Rename(tmpName, path); err != nil {
63			removeTemp()
64			return ledgerError(ErrStorage, "rename into place: %v", err)
65		}
66		if d, err := os.Open(dir); err == nil {
67			_ = d.Sync()
68			_ = d.Close()
69		}
70		return nil
71	}
72	
73	// validateAndReplay 校验全部成功记录并从冻结的初始余额重放：
74	// ID 唯一、序列连续、费用一致、int64 不溢出、任一时点余额非负，
75	// 且重放结果必须等于文件中的最终余额。任何不符都判定账本损坏。
76	func validateAndReplay(initial, final map[balanceKey]int64, records []Record) error {
77		charged := make(map[balanceKey]int64)
78		seen := map[string]bool{}
79		for i, r := range records {
80			if r.ID == "" {
81				return ledgerError(ErrCorrupt, "settlement %d has empty id", i)
82			}
83			if seen[r.ID] {
84				return ledgerError(ErrCorrupt, "duplicate settlement id %q", r.ID)
85			}
86			seen[r.ID] = true
87			if r.Account == "" || r.Asset == "" {
88				return ledgerError(ErrCorrupt, "settlement %q missing account or asset", r.ID)
89			}
90			if _, ok := initial[balanceKey{r.Account, r.Asset}]; !ok {
91				return ledgerError(ErrCorrupt, "settlement %q touches account/asset absent from initial balances", r.ID)
92			}
93			if r.Amount <= 0 || r.Fee < 0 || r.Charged <= 0 {
94				return ledgerError(ErrCorrupt, "settlement %q has non-positive amounts", r.ID)
95			}
96			if r.FeeBps < 0 || r.FeeBps > 10000 {
97				return ledgerError(ErrCorrupt, "settlement %q has invalid fee bps", r.ID)
98			}
99			if want := feeFor(r.Amount, r.FeeBps); want != r.Fee {
100				return ledgerError(ErrCorrupt, "settlement %q fee mismatch: file %d, want %d", r.ID, r.Fee, want)
101			}
102			if r.Charged != r.Amount+r.Fee {
103				return ledgerError(ErrCorrupt, "settlement %q charged != amount + fee", r.ID)
104			}
105			if int64(i)+1 != r.Seq {
106				return ledgerError(ErrCorrupt, "settlement %q sequence gap", r.ID)
107			}
108			k := balanceKey{r.Account, r.Asset}
109			sum := charged[k]
110			if r.Charged > math.MaxInt64-sum {
111				return ledgerError(ErrCorrupt, "settlement %q cumulative charges overflow int64", r.ID)
112			}
113			charged[k] = sum + r.Charged
114		}
115	
116		// 初始余额由初始化数据冻结；累计扣款不得超过它。
117		for k, start := range initial {
118			if charged[k] > start {
119				// 找到第一笔导致负余额的记录以给出更明确的报错。
120				var running int64
121				for _, r := range records {
122					if r.Account != k.account || r.Asset != k.asset {
123						continue
124					}
125					if r.Charged > start-running {
126						return ledgerError(ErrCorrupt, "settlement %q drives %s/%s negative", r.ID, r.Account, r.Asset)
127					}
128					running += r.Charged
129				}
130				return ledgerError(ErrCorrupt, "total charges for %s/%s exceed initial balance %d", k.account, k.asset, start)
131			}
132		}
133	
134		// 按记录顺序重放，末态必须与文件中的最终余额逐组合一致。
135		for k, start := range initial {
136			got := start - charged[k]
137			if want, present := final[k]; !present || got != want {
138				return ledgerError(ErrCorrupt, "final balance mismatch for %s/%s: replay %d, file %v", k.account, k.asset, got, want)
139			}
140		}
141		for k := range final {
142			if _, ok := initial[k]; !ok {
143				return ledgerError(ErrCorrupt, "final balance contains %s/%s absent from initial balances", k.account, k.asset)
144			}
145		}
146		return nil
147	}
148	
149	// checksumHex 返回 data 的 sha256 十六进制摘要，作为文档完整性凭证。
150	func checksumHex(data []byte) string {
151		sum := sha256.Sum256(data)
152		return hex.EncodeToString(sum[:])
153	}
