1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"math"
10		"os"
11		"path/filepath"
12		"sort"
13		"sync"
14	)
15	
16	// 账本磁盘格式（单文件，一个 JSON 文档，末附 sha256 校验和）：
17	//
18	//	{"version":1,
19	//	 "initial_balances":[{"account":"aa","asset":"usdc","balance":1000}],
20	//	 "balances":[{"account":"aa","asset":"usdc","balance":700}],
21	//	 "settlements":[{...一笔成功结算及其当时费率...}],
22	//	 "checksum":"<sha256 of the document without checksum>"}
23	//
24	// initial_balances 在初始化时冻结，用于检测任何对历史余额/记录的篡改；
25	// checksum 覆盖截断、比特翻转与所有语义编辑。
26	//
27	// 写入采用“临时文件 + fsync + 原子 rename + 目录 fsync”，
28	// 因此崩溃后磁盘上只会存在完整的旧版本或完整新版本，
29	// 不会出现“扣款无记录”或“记录未扣款”的中间状态。
30	const ledgerVersion = 1
31	
32	// 结算结果状态，与命令行输出一一对应，可分别识别。
33	const (
34		StatusSettled   = "settled"              // 成功扣款
35		StatusDuplicate = "duplicate"            // 幂等重试：字段与原记录一致，返回原结算，不再扣款
36		StatusConflict  = "conflict"             // 编号冲突：编号已成功但字段或费率不同
37		StatusState     = "state_error"          // 非 pending
38		StatusFunds     = "insufficient_balance" // 余额不足（含不存在的账户/资产组合）
39		StatusInvalid   = "invalid_parameter"
40		StatusStorage   = "storage_error"
41	)
42	
43	// 拒绝原因。
44	const (
45		reasonEmptyID      = "intent id must not be empty"
46		reasonEmptyAccount = "account must not be empty"
47		reasonEmptyAsset   = "asset must not be empty"
48		reasonBadAmount    = "amount must be a positive int64"
49		reasonOverflow     = "amount plus fee overflows int64"
50		reasonNotPending   = "intent is not pending"
51		reasonFunds        = "insufficient balance for amount plus fee"
52		reasonDuplicate    = "duplicate settlement attempt"
53		reasonConflict     = "settlement id conflicts with a different request"
54	)
55	
56	// BalanceInit 是初始化时一个 (账户, 资产) 组合的起始余额。
57	type BalanceInit struct {
58		Account string `json:"account"`
59		Asset   string `json:"asset"`
60		Balance int64  `json:"balance"`
61	}
62	
63	// PaymentIntent 是批次中的一项付款请求。金额使用指针以区分“缺省/null”与 0。
64	type PaymentIntent struct {
65		ID        string `json:"id"`
66		Account   string `json:"account"`
67		Paymaster string `json:"paymaster"`
68		Asset     string `json:"asset"`
69		Amount    *int64 `json:"amount"`
70		Nonce     uint64 `json:"nonce"`
71		State     string `json:"state"`
72	}
73	
74	// FeeBatch 是一次提交：固定费率（基点）+ 有序意图列表。
75	type FeeBatch struct {
76		FeeBps  int             `json:"fee_bps"`
77		Intents []PaymentIntent `json:"intents"`
78	}
79	
80	// Record 是一笔成功结算留下的永久记录，按成功先后顺序保存。
81	type Record struct {
82		ID        string `json:"id"`
83		Account   string `json:"account"`
84		Paymaster string `json:"paymaster"`
85		Asset     string `json:"asset"`
86		Amount    int64  `json:"amount"`
87		Nonce     uint64 `json:"nonce"`
88		FeeBps    int    `json:"fee_bps"`
89		Fee       int64  `json:"fee"`
90		Charged   int64  `json:"charged"`
91		Seq       int64  `json:"seq"`
92	}
93	
94	// ItemResult 是批次中一项的处理结果，顺序与输入逐项对应。
95	type ItemResult struct {
96		ID     string  `json:"id"`
97		Status string  `json:"status"`
98		Reason string  `json:"reason,omitempty"`
99		Record *Record `json:"record,omitempty"`
100	}
101	
102	// BatchResult 是一次提交的结果。空批次对应空 Results。
103	type BatchResult struct {
104		Results []ItemResult `json:"results"`
105	}
106	
107	// BalanceView 是一个 (账户, 资产) 组合的当前余额。
108	type BalanceView struct {
109		Account string `json:"account"`
110		Asset   string `json:"asset"`
111		Balance int64  `json:"balance"`
112	}
113	
114	// Snapshot 是账本查询结果。
115	type Snapshot struct {
116		Balances    []BalanceView `json:"balances"`
117		Settlements []Record      `json:"settlements"`
118	}
119	
120	// LedgerError 携带可机读分类（与 ItemResult.Status 对齐）和说明。
121	type LedgerError struct {
122		Kind    string
123		Message string
124	}
125	
126	func (e *LedgerError) Error() string { return e.Kind + ": " + e.Message }
127	
128	// 错误分类。
129	const (
130		ErrInvalid = "invalid_parameter"
131		ErrExists  = "ledger_exists"
132		ErrCorrupt = "corrupt_ledger"
133		ErrStorage = "storage_error"
134		ErrClosed  = "ledger_closed"
135		ErrNotInit = "ledger_not_initialized"
136	)
137	
138	func ledgerError(kind, format string, args ...any) error {
139		return &LedgerError{Kind: kind, Message: fmt.Sprintf(format, args...)}
140	}
141	
142	// KindOf 返回错误的分类；非账本错误按存储错误处理。
143	func KindOf(err error) string {
144		var le *LedgerError
145		if errors.As(err, &le) {
146			return le.Kind
147		}
148		return ErrStorage
149	}
150	
151	// FailWriter 注入存储故障：返回 true 时本次持久化失败，
152	// 内存状态必须回滚到该项执行之前。仅用于测试。
153	type FailWriter interface {
154		FailNextPersist() bool
155	}
156	
157	type balanceKey struct {
158		account string
159		asset   string
160	}
161	
162	type ledgerState struct {
163		Version     int
164		Initial     map[balanceKey]int64 // 初始化时冻结的起始余额，仅用于完整性校验
165		Balances    map[balanceKey]int64 // 当前余额
166		Settlements []Record
167	}
168	
169	// 磁盘文档字段（顺序即签名时的规范顺序，不得调整，否则旧文件校验失败）。
170	type unsignedDoc struct {
171		Version     int           `json:"version"`
172		Initial     []BalanceView `json:"initial_balances"`
173		Balances    []BalanceView `json:"balances"`
174		Settlements []Record      `json:"settlements"`
175	}
176	
177	type signedDoc struct {
178		unsignedDoc
179		Checksum string `json:"checksum"`
180	}
181	
182	func balanceList(m map[balanceKey]int64) []BalanceView {
183		out := make([]BalanceView, 0, len(m))
184		for k, v := range m {
185			out = append(out, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
186		}
187		sortBalances(out)
188		return out
189	}
190	
191	func balanceMap(list []BalanceView) (map[balanceKey]int64, error) {
192		out := make(map[balanceKey]int64, len(list))
193		for i, b := range list {
194			if b.Account == "" || b.Asset == "" {
195				return nil, ledgerError(ErrCorrupt, "balance %d has empty account or asset", i)
196			}
197			if b.Balance < 0 {
198				return nil, ledgerError(ErrCorrupt, "negative balance for %s/%s", b.Account, b.Asset)
199			}
200			k := balanceKey{b.Account, b.Asset}
201			if _, dup := out[k]; dup {
202				return nil, ledgerError(ErrCorrupt, "duplicate balance entry for %s/%s", b.Account, b.Asset)
203			}
204			out[k] = b.Balance
205		}
206		return out, nil
207	}
208	
209	// MarshalJSON 输出带 sha256 校验和的单个 JSON 文档。
210	func (s *ledgerState) MarshalJSON() ([]byte, error) {
211		settlements := s.Settlements
212		if settlements == nil {
213			settlements = []Record{}
214		}
215		doc := unsignedDoc{
216			Version:     s.Version,
217			Initial:     balanceList(s.Initial),
218			Balances:    balanceList(s.Balances),
219			Settlements: settlements,
220		}
221		payload, err := json.Marshal(doc)
222		if err != nil {
223			return nil, err
224		}
225		sum := checksumHex(payload)
226		out := make([]byte, 0, len(payload)+len(sum)+16)
227		out = append(out, payload[:len(payload)-1]...) // 去掉结尾 '}'
228		out = append(out, []byte(`,"checksum":"`+sum+`"}`)...)
229		return out, nil
230	}
231	
232	// UnmarshalJSON 校验 checksum、结构不变式并重放全部记录。
233	func (s *ledgerState) UnmarshalJSON(data []byte) error {
234		var doc signedDoc
235		if err := json.Unmarshal(data, &doc); err != nil {
236			return err
237		}
238		if doc.Checksum == "" {
239			return ledgerError(ErrCorrupt, "missing checksum")
240		}
241		payload, err := json.Marshal(doc.unsignedDoc)
242		if err != nil {
243			return ledgerError(ErrCorrupt, "re-encode ledger: %v", err)
244		}
245		if got := checksumHex(payload); got != doc.Checksum {
246			return ledgerError(ErrCorrupt, "checksum mismatch: file %s, want %s", doc.Checksum, got)
247		}
248		if doc.Version != ledgerVersion {
249			return ledgerError(ErrCorrupt, "unsupported ledger version %d", doc.Version)
250		}
251		initial, err := balanceMap(doc.Initial)
252		if err != nil {
253			return err
254		}
255		current, err := balanceMap(doc.Balances)
256		if err != nil {
257			return err
258		}
259		records := doc.Settlements
260		if records == nil {
261			records = []Record{}
262		}
263		if err := validateAndReplay(initial, current, records); err != nil {
264			return err
265		}
266		s.Version = doc.Version
267		s.Initial = initial
268		s.Balances = current
269		s.Settlements = records
270		return nil
271	}
272	
273	func decodeState(data []byte) (*ledgerState, error) {
274		var state ledgerState
275		if err := json.Unmarshal(data, &state); err != nil {
276			if le, ok := err.(*LedgerError); ok && le.Kind == ErrCorrupt {
277				return nil, err
278			}
279			return nil, ledgerError(ErrCorrupt, "parse ledger: %v", err)
280		}
281		return &state, nil
282	}
283	
284	// CreateLedger 在 path 处创建新账本。所有初始数据先校验，
285	// 任一不合法则返回 ErrInvalid 且不创建任何文件；
286	// 路径上已有账本则返回 ErrExists，绝不覆盖历史。
287	func CreateLedger(path string, init []BalanceInit) error {
288		if err := validateInitial(init); err != nil {
289			return err
290		}
291		abs, err := filepath.Abs(path)
292		if err != nil {
293			return ledgerError(ErrStorage, "resolve path: %v", err)
294		}
295	
296		openMu.Lock()
297		defer openMu.Unlock()
298	
299		if _, err := os.Stat(abs); err == nil {
300			return ledgerError(ErrExists, "ledger already exists at %s", abs)
301		} else if !errors.Is(err, os.ErrNotExist) {
302			return ledgerError(ErrStorage, "stat %s: %v", abs, err)
303		}
304		if openRegistry[abs] != nil {
305			return ledgerError(ErrExists, "ledger is already initialized in this process")
306		}
307	
308		state := &ledgerState{
309			Version:     ledgerVersion,
310			Initial:     make(map[balanceKey]int64, len(init)),
311			Balances:    make(map[balanceKey]int64, len(init)),
312			Settlements: []Record{},
313		}
314		for _, b := range init {
315			k := balanceKey{b.Account, b.Asset}
316			state.Initial[k] = b.Balance
317			state.Balances[k] = b.Balance
318		}
319		if err := atomicWrite(abs, state); err != nil {
320			return err
321		}
322		openRegistry[abs] = &registryEntry{state: state}
323		return nil
324	}
325	
326	func validateInitial(init []BalanceInit) error {
327		seen := map[balanceKey]bool{}
328		for i, b := range init {
329			if b.Account == "" {
330				return ledgerError(ErrInvalid, "initial balance %d: account must not be empty", i)
331			}
332			if b.Asset == "" {
333				return ledgerError(ErrInvalid, "initial balance %d: asset must not be empty", i)
334			}
335			if b.Balance < 0 {
336				return ledgerError(ErrInvalid, "initial balance %d (%s/%s): balance must be non-negative", i, b.Account, b.Asset)
337			}
338			k := balanceKey{b.Account, b.Asset}
339			if seen[k] {
340				return ledgerError(ErrInvalid, "initial balance %d: duplicate entry for %s/%s", i, b.Account, b.Asset)
341			}
342			seen[k] = true
343		}
344		return nil
345	}
346	
347	// Ledger 是一个可持久化的本地账本。同一进程内同一路径的多次 Open
348	// 返回共享同一状态与互斥锁的实例，因此并发提交按同一本账本串行化。
349	type Ledger struct {
350		path string
351		reg  *registryEntry
352		open bool
353	}
354	
355	type registryEntry struct {
356		mu       sync.Mutex // 保护 state；整个批次串行持有
357		state    *ledgerState
358		refs     int        // 打开的句柄数
359		ops      int        // 正在执行的 Submit/Query 数
360		failHook FailWriter // 仅测试注入
361	}
362	
363	// tryEvict 仅在没有句柄且没有在途操作时注销注册表项。
364	// 调用方必须持有 openMu。
365	func tryEvict(path string, reg *registryEntry) {
366		if reg.refs == 0 && reg.ops == 0 && openRegistry[path] == reg {
367			delete(openRegistry, path)
368		}
369	}
370	
371	var (
372		openMu       sync.Mutex
373		openRegistry = map[string]*registryEntry{}
374	)
375	
376	// Open 打开（或复用）path 处的账本。账本必须已由 CreateLedger 初始化；
377	// 文件缺失返回 ErrNotInit，内容损坏返回 ErrCorrupt，不会被当成空账本重来。
378	func Open(path string) (*Ledger, error) {
379		abs, err := filepath.Abs(path)
380		if err != nil {
381			return nil, ledgerError(ErrStorage, "resolve path: %v", err)
382		}
383	
384		openMu.Lock()
385		defer openMu.Unlock()
386	
387		if reg := openRegistry[abs]; reg != nil {
388			reg.refs++
389			return &Ledger{path: abs, reg: reg, open: true}, nil
390		}
391	
392		data, err := os.ReadFile(abs)
393		if err != nil {
394			if errors.Is(err, os.ErrNotExist) {
395				return nil, ledgerError(ErrNotInit, "no ledger at %s; initialize it first", abs)
396			}
397			return nil, ledgerError(ErrStorage, "read %s: %v", abs, err)
398		}
399		if len(bytes.TrimSpace(data)) == 0 {
400			return nil, ledgerError(ErrCorrupt, "ledger file %s is empty", abs)
401		}
402		dec := json.NewDecoder(bytes.NewReader(data))
403		var rawDoc json.RawMessage
404		if err := dec.Decode(&rawDoc); err != nil {
405			return nil, ledgerError(ErrCorrupt, "parse %s: %v", abs, err)
406		}
407		// 不允许尾随内容：防止文件被拼接/截断后被误读为合法。
408		if tok, err := dec.Token(); err != io.EOF {
409			if err == nil {
410				return nil, ledgerError(ErrCorrupt, "unexpected trailing data after ledger document (token %v)", tok)
411			}
412			return nil, ledgerError(ErrCorrupt, "trailing data after ledger document: %v", err)
413		}
414		state, err := decodeState(rawDoc)
415		if err != nil {
416			return nil, err
417		}
418	
419		reg := &registryEntry{state: state, refs: 1}
420		openRegistry[abs] = reg
421		return &Ledger{path: abs, reg: reg, open: true}, nil
422	}
423	
424	// Close 释放句柄；同一进程可再次 Open 同一文件并继续使用。
425	// 若关闭时有在途提交，注册表项保留到在途操作结束，避免并发 Open
426	// 从磁盘重新加载而丢失正在写入的状态。
427	func (l *Ledger) Close() error {
428		openMu.Lock()
429		defer openMu.Unlock()
430		if !l.open {
431			return nil
432		}
433		l.open = false
434		l.reg.refs--
435		tryEvict(l.path, l.reg)
436		return nil
437	}
438	
439	// beginOp 标记一次在途操作。返回 nil 表示句柄已关闭。
440	func (l *Ledger) beginOp() error {
441		openMu.Lock()
442		defer openMu.Unlock()
443		if !l.open {
444			return ledgerError(ErrClosed, "ledger handle is closed")
445		}
446		l.reg.ops++
447		return nil
448	}
449	
450	func (l *Ledger) endOp() {
451		openMu.Lock()
452		defer openMu.Unlock()
453		l.reg.ops--
454		tryEvict(l.path, l.reg)
455	}
456	
457	// feeFor 计算手续费：amount*feeBps/10000 向下取整。
458	// amount>0、0<=feeBps<=10000 时朴素乘积可能溢出 int64，
459	// 拆成商和余数两部分即可在 int64 内精确完成。
460	func feeFor(amount int64, feeBps int) int64 {
461		hi := amount / 10000
462		lo := amount % 10000
463		return hi*int64(feeBps) + (lo*int64(feeBps))/10000
464	}
465	
466	func validateIntent(it PaymentIntent) (int64, string, bool) {
467		if it.ID == "" {
468			return 0, reasonEmptyID, false
469		}
470		if it.Account == "" {
471			return 0, reasonEmptyAccount, false
472		}
473		if it.Asset == "" {
474			return 0, reasonEmptyAsset, false
475		}
476		if it.Amount == nil || *it.Amount <= 0 {
477			return 0, reasonBadAmount, false
478		}
479		return *it.Amount, "", true
480	}
481	
482	// Submit 按输入顺序结算一个批次。各项独立成功或失败：后项看到前项
483	// 成功后的余额；任一项失败不影响其余项（存储错误只回滚出错项本身，
484	// 已完成的前项不回滚）。结果与输入逐项对应，空批次返回空结果。
485	func (l *Ledger) Submit(batch FeeBatch) (*BatchResult, error) {
486		if err := l.beginOp(); err != nil {
487			return nil, err
488		}
489		defer l.endOp()
490		if batch.FeeBps < 0 || batch.FeeBps > 10000 {
491			return nil, ledgerError(ErrInvalid, "fee_bps must be within [0,10000], got %d", batch.FeeBps)
492		}
493		out := &BatchResult{Results: make([]ItemResult, 0, len(batch.Intents))}
494	
495		l.reg.mu.Lock()
496		defer l.reg.mu.Unlock()
497	
498		for i := range batch.Intents {
499			it := &batch.Intents[i]
500			res := ItemResult{ID: it.ID}
501	
502			// 1. 参数校验。未通过的编号不占用去重资格。
503			amount, reason, ok := validateIntent(*it)
504			if !ok {
505				res.Status = StatusInvalid
506				res.Reason = reason
507				out.Results = append(out.Results, res)
508				continue
509			}
510	
511			// 2. 已成功编号：字段与费率完全一致则幂等返回原记录；
512			//    任一不同则编号冲突。两者都不再扣款、不改原记录。
513			//    本批次内先成功的同编号项也在此被看到。
514			if rec, exists := l.findRecord(it.ID); exists {
515				if sameRequest(rec, it, amount, batch.FeeBps) {
516					cp := rec
517					res.Status = StatusDuplicate
518					res.Reason = reasonDuplicate
519					res.Record = &cp
520				} else {
521					res.Status = StatusConflict
522					res.Reason = reasonConflict
523				}
524				out.Results = append(out.Results, res)
525				continue
526			}
527	
528			// 3. 状态错误单独报告（不占用去重资格，之后可重新提交）。
529			if it.State != "" && it.State != "pending" {
530				res.Status = StatusState
531				res.Reason = reasonNotPending
532				out.Results = append(out.Results, res)
533				continue
534			}
535	
536			// 4. 手续费与扣款总额（溢出明确按参数错误拒绝）。
537			fee := feeFor(amount, batch.FeeBps)
538			if fee > math.MaxInt64-amount {
539				res.Status = StatusInvalid
540				res.Reason = reasonOverflow
541				out.Results = append(out.Results, res)
542				continue
543			}
544			total := amount + fee
545	
546			// 5. 余额校验。不存在的账户/资产组合余额视为 0（不足）。
547			key := balanceKey{it.Account, it.Asset}
548			bal := l.reg.state.Balances[key]
549			if total > bal {
550				res.Status = StatusFunds
551				res.Reason = reasonFunds
552				out.Results = append(out.Results, res)
553				continue
554			}
555	
556			// 6. 先在内存生效，再原子持久化；保存失败回滚该项，不留成功记录。
557			rec := Record{
558				ID:        it.ID,
559				Account:   it.Account,
560				Paymaster: it.Paymaster,
561				Asset:     it.Asset,
562				Amount:    amount,
563				Nonce:     it.Nonce,
564				FeeBps:    batch.FeeBps,
565				Fee:       fee,
566				Charged:   total,
567				Seq:       int64(len(l.reg.state.Settlements)) + 1,
568			}
569			rollback := l.stage(key, bal-total, rec)
570			if err := l.persistLocked(); err != nil {
571				rollback()
572				res.Status = StatusStorage
573				res.Reason = err.Error()
574			} else {
575				cp := rec
576				res.Status = StatusSettled
577				res.Record = &cp
578			}
579			out.Results = append(out.Results, res)
580		}
581		return out, nil
582	}
583	
584	// stage 应用一笔扣款与记录，返回回滚函数（恢复该项执行前的余额与记录长度）。
585	func (l *Ledger) stage(key balanceKey, newBal int64, rec Record) func() {
586		oldBal, hadKey := l.reg.state.Balances[key]
587		oldLen := len(l.reg.state.Settlements)
588		l.reg.state.Balances[key] = newBal
589		l.reg.state.Settlements = append(l.reg.state.Settlements, rec)
590		return func() {
591			if hadKey {
592				l.reg.state.Balances[key] = oldBal
593			} else {
594				delete(l.reg.state.Balances, key)
595			}
596			l.reg.state.Settlements = l.reg.state.Settlements[:oldLen]
597		}
598	}
599	
600	func (l *Ledger) stateView() *ledgerState { return l.reg.state }
601	
602	func (l *Ledger) findRecord(id string) (Record, bool) {
603		// 记录按成功顺序追加且 ID 唯一；条目规模在单机账本量级，直接扫描。
604		for _, r := range l.stateView().Settlements {
605			if r.ID == id {
606				return r, true
607			}
608		}
609		return Record{}, false
610	}
611	
612	// sameRequest 比较全部付款字段与费率。付款字段：账户、付款方、资产、金额、nonce。
613	func sameRequest(r Record, it *PaymentIntent, amount int64, feeBps int) bool {
614		return r.Account == it.Account &&
615			r.Paymaster == it.Paymaster &&
616			r.Asset == it.Asset &&
617			r.Amount == amount &&
618			r.Nonce == it.Nonce &&
619			r.FeeBps == feeBps
620	}
621	
622	// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
623	func (l *Ledger) Query() (*Snapshot, error) {
624		if err := l.beginOp(); err != nil {
625			return nil, err
626		}
627		defer l.endOp()
628		l.reg.mu.Lock()
629		defer l.reg.mu.Unlock()
630	
631		st := l.stateView()
632		bals := make([]BalanceView, 0, len(st.Balances))
633		for k, v := range st.Balances {
634			bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
635		}
636		sortBalances(bals)
637		recs := make([]Record, len(st.Settlements))
638		copy(recs, st.Settlements)
639		return &Snapshot{Balances: bals, Settlements: recs}, nil
640	}
641	
642	// Balance 返回单个 (账户, 资产) 组合的余额；组合不存在按 0 处理。
643	func (l *Ledger) Balance(account, asset string) (int64, error) {
644		if err := l.beginOp(); err != nil {
645			return 0, err
646		}
647		defer l.endOp()
648		l.reg.mu.Lock()
649		defer l.reg.mu.Unlock()
650		return l.stateView().Balances[balanceKey{account, asset}], nil
651	}
652	
653	func sortBalances(bals []BalanceView) {
654		sort.Slice(bals, func(i, j int) bool {
655			if bals[i].Account != bals[j].Account {
656				return bals[i].Account < bals[j].Account
657			}
658			return bals[i].Asset < bals[j].Asset
659		})
660	}
661	
662	// persistLocked 将当前状态原子写入磁盘；调用方必须持有 reg.mu。
663	func (l *Ledger) persistLocked() error {
664		if l.reg.failHook != nil && l.reg.failHook.FailNextPersist() {
665			return ledgerError(ErrStorage, "injected write failure")
666		}
667		return atomicWrite(l.path, l.stateView())
668	}
669	
670	// SetFailHook 为该路径的账本安装存储故障注入，仅用于测试。
671	func SetFailHook(l *Ledger, fw FailWriter) {
672		l.reg.failHook = fw
673	}
674

