579			t.Fatalf("balance=%d want 800 (前项与后项保留，失败项回滚)", bal)
580		}
581		snap, _ := l.Query()
582		if len(snap.Settlements) != 2 || snap.Settlements[0].ID != "ok1" || snap.Settlements[1].ID != "ok2" {
583			t.Fatalf("records after storage failure: %+v", snap.Settlements)
584		}
585	
586		// 失败编号不占去重资格，可以重新提交成功。
587		res2, _ := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("boom", "aa", "usdc", 100)}})
588		if res2.Results[0].Status != StatusSettled {
589			t.Fatalf("failed-on-storage id retry: %+v", res2.Results[0])
590		}
591	
592		// 关闭重开：磁盘状态与内存一致，失败项不留痕。
593		l2 := openOrFail(t, path)
594		snap2, _ := l2.Query()
595		if len(snap2.Settlements) != 3 {
596			t.Fatalf("after reopen want 3 records, got %+v", snap2.Settlements)
597		}
598		if bal, _ := l2.Balance("aa", "usdc"); bal != 700 {
599			t.Fatalf("after reopen balance=%d want 700", bal)
600		}
601	}
602	
603	func TestStorageFailureLeavesOldFileIntact(t *testing.T) {
604		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}})
605		l := openOrFail(t, path)
606		before, err := os.ReadFile(path)
607		if err != nil {
608			t.Fatal(err)
609		}
610		SetFailHook(l, &failOnce{remaining: 1})
611		res, _ := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("p", "aa", "usdc", 50)}})
612		if res.Results[0].Status != StatusStorage {
613			t.Fatalf("want storage_error, got %s", res.Results[0].Status)
614		}
615		after, err := os.ReadFile(path)
616		if err != nil {
617			t.Fatal(err)
618		}
619		if string(before) != string(after) {
620			t.Fatalf("failed persist must leave the old file byte-intact")
621		}
622	}
623	
624	// ---- 并发：同路径共享、同编号唯一、争用余额只成一笔 ----
625	
626	func TestConcurrentSameIDSettlesOnce(t *testing.T) {
627		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1000}})
628	
629		const n = 40
630		var wg sync.WaitGroup
631		counts := map[string]int{}
632		var mu sync.Mutex
633		wg.Add(n)
634		for i := 0; i < n; i++ {
635			go func() {
636				defer wg.Done()
637				l, err := Open(path) // 每次都重新 Open 同一路径
638				if err != nil {
639					t.Errorf("Open: %v", err)
640					return
641				}
642				defer l.Close()
643				res, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("only", "aa", "usdc", 1000)}})
644				if err != nil {
645					t.Errorf("Submit: %v", err)
646					return
647				}
648				mu.Lock()
649				counts[res.Results[0].Status]++
650				mu.Unlock()
651			}()
652		}
653		wg.Wait()
654		if counts[StatusSettled] != 1 {
655			t.Fatalf("settled=%d want 1 (counts=%v)", counts[StatusSettled], counts)
656		}
657		if counts[StatusDuplicate] != n-1 {
658			t.Fatalf("duplicate=%d want %d (counts=%v)", counts[StatusDuplicate], n-1, counts)
659		}
660		l := openOrFail(t, path)
661		if bal, _ := l.Balance("aa", "usdc"); bal != 0 {
662			t.Fatalf("balance=%d want 0", bal)
663		}
664		snap, _ := l.Query()
665		if len(snap.Settlements) != 1 {
666			t.Fatalf("records=%d want 1", len(snap.Settlements))
667		}
668	}
669	
670	func TestConcurrentContendedBalanceOnlyOneWins(t *testing.T) {
671		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1000}})
672	
673		const n = 40
674		var wg sync.WaitGroup
675		counts := map[string]int{}
676		var mu sync.Mutex
677		wg.Add(n)
678		for i := 0; i < n; i++ {
679			i := i
680			go func() {
681				defer wg.Done()
682				l := openOrFail(t, path)
683				res, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
684					intent(fmt.Sprintf("p-%d", i), "aa", "usdc", 1000),
685				}})
686				if err != nil {
687					t.Errorf("Submit: %v", err)
688					return
689				}
690				mu.Lock()
691				counts[res.Results[0].Status]++
692				mu.Unlock()
693			}()
694		}
695		wg.Wait()
696		if counts[StatusSettled] != 1 {
697			t.Fatalf("settled=%d want exactly 1 (counts=%v)", counts[StatusSettled], counts)
698		}
699		if counts[StatusFunds] != n-1 {
700			t.Fatalf("insufficient=%d want %d (counts=%v)", counts[StatusFunds], n-1, counts)
701		}
702	}
703	
704	// ---- 既有 API 仍可用 ----
705	
706	func TestLegacyExecuteBranches(t *testing.T) {
707		// 非 pending。
708		if s := Execute(Intent{ID: "a", State: "done"}, 0, map[string]bool{}, 10); s.Status != "rejected" || s.Reason != "intent is not pending" {
709			t.Fatalf("not pending: %+v", s)
710		}
711		// 已花费编号。
712		if s := Execute(Intent{ID: "a", State: "pending"}, 0, map[string]bool{"a": true}, 10); s.Status != "rejected" || s.Reason != "duplicate settlement attempt" {
713			t.Fatalf("spent: %+v", s)
714		}
715		// 余额不足（amount=101 > balance=100，bps=0）。
716		if s := Execute(Intent{ID: "a", State: "pending", Amount: 101}, 0, map[string]bool{}, 100); s.Status != "failed" {
717			t.Fatalf("insufficient: %+v", s)
718		}
719		// 成功时费用与扣款正确并标记 spent。
720		spent := map[string]bool{}
721		s := Execute(Intent{ID: "a", State: "pending", Amount: 10000}, 10, spent, 20000)
722		if s.Status != "settled" || s.Charged != 10010 || s.FeeBps != 10 || s.Ref != "settle:a" || !spent["a"] {
723			t.Fatalf("settle: %+v spent=%v", s, spent)
724		}
725	}
726	
727	func TestLegacyExecuteAndReconcile(t *testing.T) {
728		spent := map[string]bool{}
729		s := Execute(Intent{ID: "x", State: "pending", Amount: 100}, 0, spent, 100)
730		if s.Status != "settled" {
731			t.Fatalf("legacy execute: %+v", s)
732		}
733		if gaps := Reconcile(
734			[]Intent{{ID: "x"}, {ID: "missing"}},
735			[]Settlement{{Intent: "x", Status: "settled"}},
736		); len(gaps) != 1 || gaps[0] != "missing" {
737			t.Fatalf("legacy reconcile gaps=%v", gaps)
738		}
739	}
